CREATE TABLE IF NOT EXISTS "authors" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Byline shown on published posts.
	"display_name" VARCHAR(120) NOT NULL,
	-- URL segment for the author archive page.
	"slug" VARCHAR(140) NOT NULL UNIQUE,
	-- Short biography rendered under posts.
	"bio" TEXT,
	-- Profile image, referencing the media library rather than a loose URL.
	"avatar_asset_id" BIGINT,
	-- admin | editor | author | contributor. A contributor can draft but not publish.
	"role" VARCHAR(24) NOT NULL DEFAULT 'author',
	-- False when someone leaves; their published posts keep their byline.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "authors" IS 'Anyone who can write. Authors are deactivated rather than deleted, because a published post must keep resolving its byline.';
COMMENT ON COLUMN "authors"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "authors"."email" IS 'Login identity.';
COMMENT ON COLUMN "authors"."display_name" IS 'Byline shown on published posts.';
COMMENT ON COLUMN "authors"."slug" IS 'URL segment for the author archive page.';
COMMENT ON COLUMN "authors"."bio" IS 'Short biography rendered under posts.';
COMMENT ON COLUMN "authors"."avatar_asset_id" IS 'Profile image, referencing the media library rather than a loose URL.';
COMMENT ON COLUMN "authors"."role" IS 'admin | editor | author | contributor. A contributor can draft but not publish.';
COMMENT ON COLUMN "authors"."is_active" IS 'False when someone leaves; their published posts keep their byline.';
COMMENT ON COLUMN "authors"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "categories" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent category. Null at the top level.
	"parent_id" BIGINT,
	-- Display name.
	"name" VARCHAR(120) NOT NULL,
	-- URL segment; unique across the tree so category URLs never collide.
	"slug" VARCHAR(140) NOT NULL UNIQUE,
	-- Intro copy for the category archive page, which is also its meta description.
	"description" TEXT,
	-- Manual sort order among siblings.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "categories" IS 'A shallow hierarchy for navigation. Categories are editorial structure — one per post — while tags are open-ended labelling.';
COMMENT ON COLUMN "categories"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "categories"."parent_id" IS 'Parent category. Null at the top level.';
COMMENT ON COLUMN "categories"."name" IS 'Display name.';
COMMENT ON COLUMN "categories"."slug" IS 'URL segment; unique across the tree so category URLs never collide.';
COMMENT ON COLUMN "categories"."description" IS 'Intro copy for the category archive page, which is also its meta description.';
COMMENT ON COLUMN "categories"."position" IS 'Manual sort order among siblings.';

CREATE TABLE IF NOT EXISTS "posts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Byline author.
	"author_id" BIGINT NOT NULL,
	-- Primary category. Null for uncategorised drafts.
	"category_id" BIGINT,
	-- URL segment. Changing it should create a redirect rather than orphan the old URL.
	"slug" VARCHAR(200) NOT NULL UNIQUE,
	-- Post title, and the default source of the H1.
	"title" VARCHAR(220) NOT NULL,
	-- Summary for listings and, when no meta description is set, for search results.
	"excerpt" VARCHAR(400),
	-- Current published body, denormalised from the latest published revision so rendering is a single row read.
	"body" TEXT,
	-- draft | scheduled | published | archived.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- Publication time. A future value with status scheduled is what the publisher job looks for.
	"published_at" TIMESTAMP,
	-- Title tag override when it should differ from the H1.
	"meta_title" VARCHAR(200),
	-- Meta description override.
	"meta_description" VARCHAR(320),
	-- Set when the post is syndicated and the canonical version lives elsewhere.
	"canonical_url" VARCHAR(500),
	-- Hero image from the media library.
	"cover_asset_id" BIGINT,
	-- Estimated reading time, computed at save.
	"reading_minutes" INTEGER,
	-- Denormalised counter updated asynchronously; never read for correctness.
	"view_count" BIGINT NOT NULL DEFAULT 0,
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit time.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "posts" IS 'The article. The published body lives here so a page render is one row, while the edit history lives in post_revisions.';
COMMENT ON COLUMN "posts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "posts"."author_id" IS 'Byline author.';
COMMENT ON COLUMN "posts"."category_id" IS 'Primary category. Null for uncategorised drafts.';
COMMENT ON COLUMN "posts"."slug" IS 'URL segment. Changing it should create a redirect rather than orphan the old URL.';
COMMENT ON COLUMN "posts"."title" IS 'Post title, and the default source of the H1.';
COMMENT ON COLUMN "posts"."excerpt" IS 'Summary for listings and, when no meta description is set, for search results.';
COMMENT ON COLUMN "posts"."body" IS 'Current published body, denormalised from the latest published revision so rendering is a single row read.';
COMMENT ON COLUMN "posts"."status" IS 'draft | scheduled | published | archived.';
COMMENT ON COLUMN "posts"."published_at" IS 'Publication time. A future value with status scheduled is what the publisher job looks for.';
COMMENT ON COLUMN "posts"."meta_title" IS 'Title tag override when it should differ from the H1.';
COMMENT ON COLUMN "posts"."meta_description" IS 'Meta description override.';
COMMENT ON COLUMN "posts"."canonical_url" IS 'Set when the post is syndicated and the canonical version lives elsewhere.';
COMMENT ON COLUMN "posts"."cover_asset_id" IS 'Hero image from the media library.';
COMMENT ON COLUMN "posts"."reading_minutes" IS 'Estimated reading time, computed at save.';
COMMENT ON COLUMN "posts"."view_count" IS 'Denormalised counter updated asynchronously; never read for correctness.';
COMMENT ON COLUMN "posts"."created_at" IS 'Row creation time.';
COMMENT ON COLUMN "posts"."updated_at" IS 'Last edit time.';

CREATE INDEX "idx_posts_status_published"
ON "posts" ("status", "published_at");
CREATE INDEX "idx_posts_author_published"
ON "posts" ("author_id", "published_at");
CREATE INDEX "idx_posts_category"
ON "posts" ("category_id");

CREATE TABLE IF NOT EXISTS "post_revisions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Post this revision belongs to.
	"post_id" BIGINT NOT NULL,
	-- Who made the edit. Null if that account was deleted.
	"author_id" BIGINT,
	-- Monotonic counter per post, so revisions order without relying on timestamps.
	"revision_number" INTEGER NOT NULL,
	-- Title at this revision.
	"title" VARCHAR(220) NOT NULL,
	-- Body at this revision.
	"body" TEXT,
	-- Editor note describing the change.
	"change_summary" VARCHAR(255),
	-- Marks the revision currently live, which is what a rollback restores.
	"is_published_version" BOOLEAN NOT NULL DEFAULT false,
	-- When the revision was saved.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "post_revisions" IS 'Append-only edit history. Keeping revisions in their own table means the hot posts table stays narrow and a rollback is an insert, not a restore from backup.';
COMMENT ON COLUMN "post_revisions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "post_revisions"."post_id" IS 'Post this revision belongs to.';
COMMENT ON COLUMN "post_revisions"."author_id" IS 'Who made the edit. Null if that account was deleted.';
COMMENT ON COLUMN "post_revisions"."revision_number" IS 'Monotonic counter per post, so revisions order without relying on timestamps.';
COMMENT ON COLUMN "post_revisions"."title" IS 'Title at this revision.';
COMMENT ON COLUMN "post_revisions"."body" IS 'Body at this revision.';
COMMENT ON COLUMN "post_revisions"."change_summary" IS 'Editor note describing the change.';
COMMENT ON COLUMN "post_revisions"."is_published_version" IS 'Marks the revision currently live, which is what a rollback restores.';
COMMENT ON COLUMN "post_revisions"."created_at" IS 'When the revision was saved.';

CREATE UNIQUE INDEX "uq_revisions_post_number"
ON "post_revisions" ("post_id", "revision_number");

CREATE TABLE IF NOT EXISTS "tags" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Display label.
	"name" VARCHAR(80) NOT NULL,
	-- URL segment for the tag archive.
	"slug" VARCHAR(100) NOT NULL UNIQUE,
	-- Denormalised count for tag clouds and cleanup of unused tags.
	"usage_count" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "tags" IS 'Open-ended labels. Unlike categories, tags are many-per-post and flat.';
COMMENT ON COLUMN "tags"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "tags"."name" IS 'Display label.';
COMMENT ON COLUMN "tags"."slug" IS 'URL segment for the tag archive.';
COMMENT ON COLUMN "tags"."usage_count" IS 'Denormalised count for tag clouds and cleanup of unused tags.';

CREATE TABLE IF NOT EXISTS "post_tags" (
	-- Post being tagged. Half of the composite primary key.
	"post_id" BIGINT,
	-- Tag applied. The other half of the composite key, which makes a duplicate tagging impossible.
	"tag_id" BIGINT,
	-- When the tag was applied.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("post_id", "tag_id")
);

COMMENT ON TABLE "post_tags" IS 'Join table with a composite primary key rather than a surrogate id. There is nothing to say about the relationship beyond its existence, so the pair is the key.';
COMMENT ON COLUMN "post_tags"."post_id" IS 'Post being tagged. Half of the composite primary key.';
COMMENT ON COLUMN "post_tags"."tag_id" IS 'Tag applied. The other half of the composite key, which makes a duplicate tagging impossible.';
COMMENT ON COLUMN "post_tags"."added_at" IS 'When the tag was applied.';

CREATE INDEX "idx_post_tags_tag"
ON "post_tags" ("tag_id");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Post being discussed.
	"post_id" BIGINT NOT NULL,
	-- Comment being replied to. Null for a top-level comment.
	"parent_id" BIGINT,
	-- Registered author, when the commenter is a staff account.
	"author_id" BIGINT,
	-- Display name for an anonymous commenter.
	"guest_name" VARCHAR(120),
	-- Email for an anonymous commenter, used for notifications and moderation, never displayed.
	"guest_email" VARCHAR(320),
	-- Comment text. Stored as written and escaped at render time.
	"body" TEXT NOT NULL,
	-- pending | approved | spam | deleted. Nothing is hard-deleted, so a thread does not lose its shape.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Source address, kept for spam scoring. Long enough for IPv6.
	"ip_address" VARCHAR(45),
	-- Submission time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Threaded comments via a self-reference. Soft deletion keeps replies attached to something, and the composite index is what makes rendering an approved thread a single range scan.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."post_id" IS 'Post being discussed.';
COMMENT ON COLUMN "comments"."parent_id" IS 'Comment being replied to. Null for a top-level comment.';
COMMENT ON COLUMN "comments"."author_id" IS 'Registered author, when the commenter is a staff account.';
COMMENT ON COLUMN "comments"."guest_name" IS 'Display name for an anonymous commenter.';
COMMENT ON COLUMN "comments"."guest_email" IS 'Email for an anonymous commenter, used for notifications and moderation, never displayed.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text. Stored as written and escaped at render time.';
COMMENT ON COLUMN "comments"."status" IS 'pending | approved | spam | deleted. Nothing is hard-deleted, so a thread does not lose its shape.';
COMMENT ON COLUMN "comments"."ip_address" IS 'Source address, kept for spam scoring. Long enough for IPv6.';
COMMENT ON COLUMN "comments"."created_at" IS 'Submission time.';

CREATE INDEX "idx_comments_post_status_time"
ON "comments" ("post_id", "status", "created_at");
CREATE INDEX "idx_comments_parent"
ON "comments" ("parent_id");

CREATE TABLE IF NOT EXISTS "media_assets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Author who uploaded the file.
	"uploaded_by_id" BIGINT,
	-- Object storage key. The database stores the pointer; the bytes live in object storage.
	"storage_key" VARCHAR(500) NOT NULL UNIQUE,
	-- Original filename, kept for downloads.
	"filename" VARCHAR(255) NOT NULL,
	-- Content type, e.g. image/webp.
	"mime_type" VARCHAR(100) NOT NULL,
	-- File size in bytes.
	"byte_size" BIGINT NOT NULL,
	-- Pixel width for images, so markup can reserve space and avoid layout shift.
	"width" INTEGER,
	-- Pixel height for images.
	"height" INTEGER,
	-- Alternative text. Stored with the asset so every use inherits accessible markup.
	"alt_text" VARCHAR(300),
	-- Upload time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "media_assets" IS 'A media library rather than URLs pasted into post bodies. Alt text and dimensions live with the asset, so accessibility and layout stability are properties of the file, not of each embed.';
COMMENT ON COLUMN "media_assets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "media_assets"."uploaded_by_id" IS 'Author who uploaded the file.';
COMMENT ON COLUMN "media_assets"."storage_key" IS 'Object storage key. The database stores the pointer; the bytes live in object storage.';
COMMENT ON COLUMN "media_assets"."filename" IS 'Original filename, kept for downloads.';
COMMENT ON COLUMN "media_assets"."mime_type" IS 'Content type, e.g. image/webp.';
COMMENT ON COLUMN "media_assets"."byte_size" IS 'File size in bytes.';
COMMENT ON COLUMN "media_assets"."width" IS 'Pixel width for images, so markup can reserve space and avoid layout shift.';
COMMENT ON COLUMN "media_assets"."height" IS 'Pixel height for images.';
COMMENT ON COLUMN "media_assets"."alt_text" IS 'Alternative text. Stored with the asset so every use inherits accessible markup.';
COMMENT ON COLUMN "media_assets"."created_at" IS 'Upload time.';

CREATE TABLE IF NOT EXISTS "slug_redirects" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Old path, including the leading slash. Unique so lookup is a single index hit.
	"from_path" VARCHAR(500) NOT NULL UNIQUE,
	-- Destination path.
	"to_path" VARCHAR(500) NOT NULL,
	-- 301 for a permanent move, 302 while a change is provisional.
	"status_code" INTEGER NOT NULL DEFAULT 301,
	-- Post the redirect was created for, when it came from a slug change.
	"post_id" BIGINT,
	-- When the redirect was created.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "slug_redirects" IS 'Every slug change writes a row here. It is the cheapest possible insurance against losing accumulated search rankings and inbound links, and the router checks it before rendering a 404.';
COMMENT ON COLUMN "slug_redirects"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "slug_redirects"."from_path" IS 'Old path, including the leading slash. Unique so lookup is a single index hit.';
COMMENT ON COLUMN "slug_redirects"."to_path" IS 'Destination path.';
COMMENT ON COLUMN "slug_redirects"."status_code" IS '301 for a permanent move, 302 while a change is provisional.';
COMMENT ON COLUMN "slug_redirects"."post_id" IS 'Post the redirect was created for, when it came from a slug change.';
COMMENT ON COLUMN "slug_redirects"."created_at" IS 'When the redirect was created.';

CREATE TABLE IF NOT EXISTS "subscribers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscriber address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- pending | confirmed | unsubscribed | bounced. Only confirmed addresses are mailed.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Hash of the double opt-in token. The plaintext only ever exists in the email.
	"confirmation_token_hash" VARCHAR(255),
	-- When double opt-in completed.
	"confirmed_at" TIMESTAMP,
	-- Unsubscribe time. The row is kept so a resubscribe is auditable and a suppression list is possible.
	"unsubscribed_at" TIMESTAMP,
	-- Where the signup came from, e.g. post_footer or homepage.
	"source" VARCHAR(40),
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscribers" IS 'Newsletter list with double opt-in. Unsubscribes are retained rather than deleted, because a deleted row is an address you will accidentally mail again.';
COMMENT ON COLUMN "subscribers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscribers"."email" IS 'Subscriber address.';
COMMENT ON COLUMN "subscribers"."status" IS 'pending | confirmed | unsubscribed | bounced. Only confirmed addresses are mailed.';
COMMENT ON COLUMN "subscribers"."confirmation_token_hash" IS 'Hash of the double opt-in token. The plaintext only ever exists in the email.';
COMMENT ON COLUMN "subscribers"."confirmed_at" IS 'When double opt-in completed.';
COMMENT ON COLUMN "subscribers"."unsubscribed_at" IS 'Unsubscribe time. The row is kept so a resubscribe is auditable and a suppression list is possible.';
COMMENT ON COLUMN "subscribers"."source" IS 'Where the signup came from, e.g. post_footer or homepage.';
COMMENT ON COLUMN "subscribers"."created_at" IS 'Signup time.';

CREATE INDEX "idx_subscribers_status"
ON "subscribers" ("status");

ALTER TABLE "authors"
ADD FOREIGN KEY("avatar_asset_id") REFERENCES "media_assets"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "categories"
ADD FOREIGN KEY("parent_id") REFERENCES "categories"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "posts"
ADD FOREIGN KEY("author_id") REFERENCES "authors"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "posts"
ADD FOREIGN KEY("category_id") REFERENCES "categories"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "posts"
ADD FOREIGN KEY("cover_asset_id") REFERENCES "media_assets"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "post_revisions"
ADD FOREIGN KEY("post_id") REFERENCES "posts"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "post_revisions"
ADD FOREIGN KEY("author_id") REFERENCES "authors"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "post_tags"
ADD FOREIGN KEY("post_id") REFERENCES "posts"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "post_tags"
ADD FOREIGN KEY("tag_id") REFERENCES "tags"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "comments"
ADD FOREIGN KEY("post_id") REFERENCES "posts"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "comments"
ADD FOREIGN KEY("parent_id") REFERENCES "comments"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "comments"
ADD FOREIGN KEY("author_id") REFERENCES "authors"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "media_assets"
ADD FOREIGN KEY("uploaded_by_id") REFERENCES "authors"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "slug_redirects"
ADD FOREIGN KEY("post_id") REFERENCES "posts"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
